query AuditTeam($key: String!) {
  teams(first: 2, filter: { key: { eqIgnoreCase: $key } }) {
    nodes {
      id key triageEnabled
      defaultIssueState { id name type }
      states(first: 50) {
        nodes { id name type position }
        pageInfo { hasNextPage endCursor }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query AuditReceipts($id: String!, $comment: String!, $attachment: String!, $relation: String!) {
  organization { id urlKey }
  issue(id: $id) {
    id identifier archivedAt trashed title description url branchName priority estimate dueDate
    state { id name type color }
    assignee { id name displayName }
    project { id name slugId }
    projectMilestone { id name }
    cycle { id number name isActive isNext isPrevious isFuture isPast }
    team { id key activeCycle { number } }
    parent { id identifier title state { name color } }
    labels(first: 250) { nodes { id name color } pageInfo { hasNextPage endCursor } }
  }
  c0: comment(id: $comment) { id issue { id } }
  a0: attachment(id: $attachment) { id issue { id } }
  r0: issueRelation(id: $relation) { id issue { id } relatedIssue { id } }
}
